package com.bank.undo;

import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class StackDemo {
    private static final Logger log = Logger.getLogger(StackDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        ActionStack actions = new ActionStack();
        actions.push("ADD_PAYEE Priya");
        actions.push("SET_LIMIT 50000");
        actions.push("ENABLE_SMS_ALERT");

        log.info(() -> "Top action (peek): " + actions.peek());

        // Undo in LIFO order: last pushed is first popped
        while (!actions.isEmpty()) {
            String undone = actions.pop();
            log.info(() -> "Undoing: " + undone);
        }

        log.info(() -> "Undo on empty stack handled: " + actions.safePop());
    }
}

class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
