package com.bank.undo;

import java.util.ArrayDeque;
import java.util.Deque;

class ActionStack {
    // ArrayDeque is the modern, faster choice for a stack.
    private final Deque<String> stack = new ArrayDeque<>();

    void push(String action) {
        stack.push(action);           // add to top — O(1)
    }

    String pop() {
        if (stack.isEmpty()) {
            throw new IllegalStateException("no action to undo");
        }
        return stack.pop();           // remove and return top — O(1)
    }

    String peek() {
        if (stack.isEmpty()) {
            throw new IllegalStateException("stack is empty");
        }
        return stack.peek();          // look at top without removing — O(1)
    }

    boolean isEmpty() {
        return stack.isEmpty();
    }

    // Safe variant: returns a message instead of throwing on empty.
    String safePop() {
        return stack.isEmpty() ? "nothing to undo" : stack.pop();
    }
}
